"""Русский язык, 4 класс."""
from rus_common import *


def t_speech_text(r):
    t = []
    t.append(ch("Что такое текст?", "группа предложений, связанных темой и главной мыслью", ["любые предложения подряд", "одно длинное предложение"], "Признаки текста: тема, главная мысль, связность, заголовок.", "Что объединяет предложения?"))
    t.append(order("Расставь части плана текста «Как мы спасли щенка».", ["Находка у подъезда", "Щенок замёрз", "Тёплый приют дома", "Новый друг"], "План отражает последовательность событий.", "Что было сначала?"))
    t.append(ch("Какой тип текста отвечает на вопрос «почему?»", "рассуждение", ["описание", "повествование"], "Рассуждение объясняет причины.", "Объяснение."))
    t.append(ch("Как называется отступ в начале части текста?", "красная строка (абзац)", ["заголовок", "сноска"], "Каждая микротема — с красной строки.", "Отступ."))
    t.append(multi("Что относится к признакам хорошей речи?", ["точность", "выразительность", "уместность"], ["многословие", "грубость"], "Хорошая речь — точная, выразительная, уместная.", "Как говорят хорошие рассказчики?"))
    t.append(tf("Главная мысль текста часто выражена в заголовке или в последнем предложении.", True, "Часто так бывает.", "Где автор подводит итог?"))
    t.append(sort_("Разложи по типам текста.", [("Описание", ["Какая красивая осень: золото, багрянец, синее небо…"]), ("Повествование", ["Утром мы вышли, потом поднялись на гору, а вечером вернулись."]), ("Рассуждение", ["Книги нужно беречь, потому что в них хранятся знания."])], "Тип текста — по вопросу к нему.", "Какой? Что было? Почему?"))
    t.append(fill("Изложение — это пересказ текста ___.", "письменно", ["устно в песне", "без слов"], "Изложение — письменный пересказ.", "На бумаге."))
    t.append(ch("Чем сочинение отличается от изложения?", "в сочинении пишут свои мысли", ["в сочинении переписывают текст", "ничем"], "Сочинение — собственный текст.", "Чьи мысли?"))
    t.append(fix("Найди ошибку: «Текст-описание отвечает на вопрос „что произошло?“».", ["описание", "что", "произошло?"], 0, "повествование", ["рассуждение", "диалог"], "«Что произошло?» — повествование.", "События."))
    return t


def t_sentence(r):
    t = []
    for s, a in [("Как прекрасна наша земля!", "повествовательное, восклицательное"), ("Ты пойдёшь завтра в театр?", "вопросительное, невосклицательное"), ("Береги природу!", "побудительное, восклицательное")]:
        t.append(ch(f"Охарактеризуй предложение: «{s}»", a, [x for x in ["повествовательное, восклицательное", "вопросительное, невосклицательное", "побудительное, восклицательное", "повествовательное, невосклицательное"] if x != a][:3], "Определяем цель высказывания и интонацию.", "Сообщает, спрашивает или побуждает?"))
    for s, a in [("Дорогой друг, приезжай к нам.", "Дорогой друг"), ("Расскажи нам, Оля, о поездке.", "Оля"), ("Шуми, шуми, послушное ветрило.", "послушное ветрило")]:
        t.append(ch(f"Найди обращение: «{s}»", a, [w.strip(",.") for w in s.split() if w.strip(",.") not in a.split()][:3], "Обращение называет того, к кому обращаются, и выделяется запятыми.", "К кому обращаются?"))
    t.append(fix("Найди ошибку: «Ребята давайте дружить!»", ["Ребята", "давайте", "дружить!"], 0, "Ребята,", ["Ребята.", "Ребята!"], "Обращение выделяется запятой.", "Где запятая?"))
    t.append(tf("Обращение может стоять в начале, середине или конце предложения.", True, "Например: «Спасибо, мама».", "Где бывает обращение?"))
    t.append(multi("Выбери предложения с обращением.", ["Здравствуй, зимушка-зима!", "Сынок, помоги мне."], ["Зима пришла.", "Сын помогает."], "Обращение — к кому обращаются.", "Есть ли обращение?"))
    t.append(fill("Обращение выделяется ___.", "запятыми", ["кавычками", "тире"], "Обращение отделяется запятыми.", "Знак препинания."))
    return t


def t_homogeneous(r):
    t = []
    for s, a in [("В саду растут яблони, груши и сливы.", ["яблони", "груши", "сливы"]), ("Дети бегали, прыгали и смеялись.", ["бегали", "прыгали", "смеялись"]), ("На лугу цветут белые, жёлтые, синие цветы.", ["белые", "жёлтые", "синие"])]:
        t.append(multi(f"Найди однородные члены: «{s}»", a, [w.strip(",.") for w in s.split() if w.strip(",.") not in a and len(w) > 2][:2], "Однородные члены отвечают на один вопрос и относятся к одному слову.", "Одинаковый вопрос к одному слову."))
    t.append(ch("Что такое однородные члены предложения?", "члены, отвечающие на один вопрос и относящиеся к одному слову", ["слова, начинающиеся с одной буквы", "подлежащее и сказуемое"], "Однородные члены перечисляются.", "Перечисление."))
    t.append(ch("Какими могут быть однородные члены?", "и главными, и второстепенными", ["только подлежащими", "только сказуемыми"], "Однородными бывают любые члены предложения.", "Пример: дети бегали и прыгали."))
    t.append(tf("Однородные члены связаны интонацией перечисления или союзами.", True, "Союзы: и, а, но, или.", "Как произносят перечисление?"))
    t.append(sort_("Есть ли однородные члены?", [("Есть", ["Мы купили хлеб, молоко и сыр.", "Ветер выл и стонал."]), ("Нет", ["Мы купили свежий хлеб.", "Ветер выл всю ночь."])], "Ищи перечисление.", "Есть ли перечисление?"))
    t.append(fill("Союзы при однородных членах: и, а, ___.", "но", ["что", "чтобы"], "И, а, но — частые союзы.", "Противительный союз."))
    t.append(match("Соедини однородные члены и вопрос.", [("бегали, прыгали", "что делали?"), ("красные, жёлтые", "какие?"), ("кошки, собаки", "кто?")], "Однородные отвечают на один вопрос.", "Какой вопрос?"))
    t.append(fix("Найди ошибку: «однородные члены относятся к разным словам».", ["однородные", "члены", "относятся", "к", "разным"], 4, "одному", ["двум", "главным"], "Однородные члены относятся к одному слову.", "К скольким словам?"))
    return t


def t_homog_punct(r):
    t = []
    for s, a in [("Зима бывает снежной___ морозной.", ","), ("Я люблю яблоки и___ груши.", "нет знака"), ("Ёжик маленький___ но храбрый.", ","), ("Мы читали___ писали и решали задачи.", ",")]:
        t.append(fill(s, a, [x for x in [",", "нет знака", "—"] if x != a], "Запятая ставится между однородными членами без союзов и перед союзами а, но; перед одиночным «и» запятая не ставится.", "Есть ли союз «и»?"))
    t.append(ch("Ставится ли запятая перед одиночным союзом «и» между однородными членами?", "нет", ["да", "всегда"], "Пример: «кошка и собака».", "Одиночный союз «и»."))
    t.append(ch("Перед какими союзами ставится запятая при однородных членах?", "а, но", ["и (одиночный)", "или (одиночный)"], "Противительные союзы а, но требуют запятой.", "Противопоставление."))
    t.append(fix("Найди ошибку: «Он устал но, продолжал работать».", ["Он", "устал", "но,", "продолжал"], 1, "устал,", ["устал.", "устал!"], "Запятая ставится перед союзом «но».", "Перед но."))
    t.append(multi("Выбери предложения, где запятые расставлены верно.", ["Шёл дождь, гремел гром.", "Птицы пели, но тихо."], ["Мама, и папа ушли.", "Я, люблю, читать."], "Запятые — между однородными без союза и перед но.", "Проверь союзы."))
    t.append(tf("В предложении «Летом я купался, загорал и рыбачил» запятая стоит верно.", True, "Между «купался, загорал» — без союза, перед «и» — нет.", "Проверь правило."))
    t.append(build("Расставь: «Мы, гуляли, и, играли».", ["Мы", "гуляли", "и", "играли."], ["гуляли,"], "Мы гуляли и играли. Перед одиночным «и» запятой нет.", "Без запятой перед и."))
    return t


def t_simple_complex(r):
    t = []
    for s, a in [("Небо потемнело, и пошёл дождь.", "сложное"), ("Небо потемнело и затянулось тучами.", "простое с однородными сказуемыми"), ("Солнце светит, но не греет.", "простое с однородными сказуемыми"), ("Солнце село, а луна взошла.", "сложное")]:
        t.append(ch(f"Какое это предложение: «{s}»?", a, [x for x in ["сложное", "простое с однородными сказуемыми"] if x != a], "В сложном предложении две основы (два подлежащих со сказуемыми).", "Сколько подлежащих?"))
    t.append(ch("Сколько основ в предложении «Зазвенел звонок, ученики вошли в класс»?", "две", ["одна", "три"], "Звонок зазвенел; ученики вошли.", "Найди подлежащие."))
    t.append(fill("В сложном предложении части разделяются ___.", "запятой", ["двоеточием всегда", "кавычками"], "Обычно ставится запятая.", "Знак между частями."))
    t.append(sort_("Простое или сложное?", [("Простое", ["Мы шли и пели.", "Кот спит."]), ("Сложное", ["Мы шли, а птицы пели.", "Кот спит, мышь бегает."])], "Считай основы.", "Сколько подлежащих?"))
    t.append(fix("Найди ошибку: «Подул ветер и зашумели деревья».", ["ветер", "и", "зашумели"], 0, "ветер,", ["ветер.", "ветер —"], "Это сложное предложение: перед «и» нужна запятая.", "Две основы."))
    t.append(multi("Выбери сложные предложения.", ["Я пишу, а брат читает.", "Стемнело, зажглись фонари."], ["Я пишу и читаю.", "Зажглись яркие фонари."], "Две основы — сложное.", "Найди основы."))
    t.append(tf("Предложение с однородными сказуемыми — простое.", True, "У него одна основа.", "Одно подлежащее."))
    return t


def t_lexis(r):
    t = []
    t.append(ch("Какое слово устаревшее?", "кафтан", ["куртка", "телефон", "компьютер"], "Кафтан — старинная одежда, слово устарело.", "Что носили давно?"))
    t.append(ch("Какое слово новое (неологизм)?", "смартфон", ["изба", "лапти", "кольчуга"], "Смартфон — новое слово.", "Что появилось недавно?"))
    t.append(match("Соедини слово и значение.", [("перст", "палец"), ("очи", "глаза"), ("уста", "губы")], "Это устаревшие слова.", "Встречаются в стихах и сказках."))
    t.append(sort_("Разложи слова.", [("Синонимы к «большой»", ["огромный", "громадный"]), ("Антонимы к «большой»", ["маленький", "крошечный"])], "Синонимы и антонимы.", "Похожи или противоположны?"))
    t.append(ch("Что значит заимствованное слово?", "слово, пришедшее из другого языка", ["слово, взятое на время", "старое слово"], "Например: футбол — из английского.", "Пришло из другого языка."))
    t.append(fill("Слова с противоположным значением — это ___.", "антонимы", ["синонимы", "омонимы"], "Антонимы.", "Противоположные."))
    t.append(multi("Выбери фразеологизмы.", ["бить баклуши", "зарубить на носу"], ["читать книгу", "пить чай"], "Фразеологизмы — устойчивые выражения.", "Образные выражения."))
    t.append(ch("Что значит «работать спустя рукава»?", "небрежно", ["быстро", "в перчатках"], "Спустя рукава — плохо, небрежно.", "Образно."))
    t.append(tf("«Ключ» (родник) и «ключ» (от замка) — омонимы.", True, "Одинаково звучат, значения разные.", "Связаны ли значения?"))
    t.append(fix("Найди ошибку: «Слова „храбрый“ и „смелый“ — антонимы».", ["храбрый", "смелый", "антонимы"], 2, "синонимы", ["омонимы", "паронимы"], "Близкие по значению — синонимы.", "Похожи по смыслу."))
    return t


def t_composition(r):
    t = []
    for w, p, root, s, e in [("подоконник", "под", "окон", "ник", "нулевое"), ("пригородный", "при", "город", "н", "ый"), ("рассказчик", "рас", "сказ", "чик", "нулевое"), ("безоблачный", "без", "облач", "н", "ый")]:
        t.append(ch(f"Найди корень в слове «{w}».", root, [p, s, w[:4]], f"{w}: приставка {p}, корень {root}, суффикс {s}, окончание {e}.", "Подбери однокоренное слово."))
        t.append(ch(f"Найди приставку в слове «{w}».", p, [root, s, w[:2] if w[:2] != p else w[:3]], f"Приставка — «{p}».", "Что стоит перед корнем?"))
    t.append(order("Порядок разбора слова по составу.", ["окончание", "основа", "корень", "суффикс", "приставка"], "Сначала окончание и основа, потом корень, затем суффикс и приставка.", "Начни с изменяемой части."))
    t.append(tf("В слове может не быть приставки и суффикса, но корень есть всегда.", True, "Без корня слов не бывает.", "Главная часть."))
    t.append(fix("Найди ошибку: «В слове „лесник“ окончание „ник“».", ["окончание", "ник"], 1, "нулевое", ["ик", "лес"], "Лесник — окончание нулевое, «-ник» — суффикс.", "Измени слово: лесника."))
    return t


def t_root_spelling(r):
    t = []
    data = [("р_сток", "о", "рос"), ("гр_за", "о", "грозы"), ("ск_зка", "а", "сказ"), ("бере_ка", "з", "берёза"), ("ре_кий", "д", "редок"), ("сер_це", "д", "сердечко"), ("лес_ница", "т", "лесенка"), ("в_зать", "я", "вязка")]
    for w, a, chk in r.sample(data, 7):
        opts = {"о": ["а"], "а": ["о"], "я": ["е", "и"], "з": ["с"], "д": ["т"], "т": ["нет"]}.get(a, ["е"])
        t.append(fill(f"Вставь пропущенную букву: {w.replace('_', '___')}", a, opts, f"{w.replace('_', a)} — проверочное слово «{chk}».", "Подбери проверочное слово."))
    t.append(match("Соедини орфограмму и способ проверки.", [("безударная гласная", "поставить под ударение"), ("парная согласная", "поставить перед гласной"), ("непроизносимая согласная", "найти слово, где она слышна")], "Способы проверки орфограмм в корне.", "Вспомни правила."))
    t.append(multi("Выбери слова с непроверяемыми гласными (словарные).", ["корова", "собака", "капуста"], ["вода", "трава"], "Корова, собака, капуста — словарные слова.", "Можно ли подобрать проверку?"))
    t.append(fix("Найди ошибку: «Мы гуляли по березовой ращи».", ["по", "березовой", "ращи"], 2, "роще", ["раще", "рощи"], "Роща — словарное слово, пишем «о»: по роще.", "Словарное слово."))
    return t


def t_prefix_suffix(r):
    t = []
    for w, a, d in [("р_ссказ", "а", ["о"]), ("_тлетел", "о", ["а"]), ("п_дход", "о", ["а"]), ("р_злив", "а", ["о"]), ("п_ехать", "о", ["а"])]:
        pass
    for w, right, wrong in [("прибежал", "при", "пре"), ("отправил", "от", "ат"), ("подписал", "под", "пот"), ("сделал", "с", "з"), ("рассказал", "рас", "раз")]:
        t.append(ch(f"Какая приставка в слове «{w}»?", right, [wrong], f"Приставка «{right}». Приставки пишутся одинаково, независимо от произношения (кроме приставок на з/с).", "Приставки нужно запомнить."))
    for w, s in [("дружок", "ок"), ("лисёнок", "ёнок"), ("строитель", "тель")]:
        t.append(ch(f"Найди суффикс в слове «{w}».", s, [x for x in ["ок", "ёнок", "тель", "ик", "ек"] if x != s][:2], f"Суффикс «{s}».", "После корня."))
    t.append(ch("Когда пишется приставка «раз-», а когда «рас-»?", "«рас-» перед глухим согласным, «раз-» перед звонким", ["всегда «раз-»", "всегда «рас-»"], "Рассказ — раздать.", "Звонкий или глухой следующий звук?"))
    t.append(fix("Найди ошибку: «Мы раскрасили и разсказали».", ["раскрасили", "и", "разсказали"], 2, "рассказали", ["расказали", "разказали"], "Перед глухим «с» пишем «рас-»: рассказали.", "Глухой звук после приставки."))
    return t


def t_pos(r):
    t = []
    data = [("красота", "имя существительное"), ("красивый", "имя прилагательное"), ("красиво", "наречие"), ("украсить", "глагол"), ("десять", "имя числительное"), ("он", "местоимение")]
    for w, c in data:
        t.append(ch(f"Какая часть речи «{w}»?", c, [x for _, x in data if x != c][:3], f"«{w}» — {c}.", "Задай вопрос."))
    t.append(sort_("Разложи слова.", [("Самостоятельные", ["поле", "бежать", "весело"]), ("Служебные", ["из", "и", "не"])], "Служебные: предлоги, союзы, частицы.", "Отвечает ли на вопрос?"))
    t.append(match("Соедини часть речи и признак.", [("наречие", "не изменяется"), ("существительное", "имеет род, число, падеж"), ("глагол", "имеет время")], "Признаки частей речи.", "Что умеет изменяться?"))
    t.append(fix("Найди ошибку: «„Быстро“ — прилагательное».", ["Быстро", "—", "прилагательное"], 2, "наречие", ["глагол", "существительное"], "Быстро — как? — наречие.", "Вопрос как?"))
    t.append(multi("Выбери союзы.", ["и", "а", "но"], ["на", "под", "не"], "Союзы связывают слова и предложения.", "Связывают части."))
    return t


def t_adverb(r):
    t = []
